select case when year(p.launch_date) < 2024 then 'before_2024' when year(p.launch_date) = 2024 then '2024' else 'after_2024' end as launch_cohort, min(ss.revenue) as min_revenue from store_sales ss right outer join products p on ss.product_id = p.id join suppliers s on p.supplier_id = s.id group by case when year(p.launch_date) < 2024 then 'before_2024' when year(p.launch_date) = 2024 then '2024' else 'after_2024' end order by min_revenue desc
